#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    const char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0 || len > 31) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (input[i] != '0' && input[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    // Determine if overflow (all ones)
    int all_one = 1;
    for (size_t i = 0; i < len; ++i) {
        if (input[i] == '0') { all_one = 0; break; }
    }
    // Compute steps as observed by the original Turing machine:
    // The machine moves right over each bit, then moves left over each trailing '1', flips a bit, and stops.
    // Steps are counted for each head move (right or left) and for the final write operation.
    int steps = 0;
    // Move right over all bits (len moves)
    steps += (int)len;
    if (all_one) {
        // For overflow, after reaching the end it moves left over all bits and writes '0' at the most significant position.
        steps += (int)len; // left moves over all bits
        steps += 1; // final write step
        puts("OVERFLOW");
        printf(" steps=%d\n", steps);
        return 0;
    }
    // Find number of trailing '1's (least significant side is the rightmost character)
    int trailing_ones = 0;
    for (ssize_t i = (ssize_t)len - 1; i >= 0 && input[i] == '1'; --i) {
        trailing_ones++;
    }
    // After moving right to the end, the machine moves left over the trailing ones.
    steps += trailing_ones; // left moves over each trailing '1'
    steps += 1; // final write (flipping the first '0' to '1')

    // Perform binary increment (LSB is the rightmost character)
    char *result = malloc(len + 1);
    if (!result) return 1;
    strcpy(result, input);
    // Flip trailing ones to '0'
    for (int i = (int)len - 1; i >= 0 && result[i] == '1'; --i) {
        result[i] = '0';
    }
    // Flip the first '0' to '1'
    for (int i = (int)len - 1; i >= 0; --i) {
        if (result[i] == '0') { result[i] = '1'; break; }
    }
    // Output result and steps in the same format as the original program
    printf("result=");
    for (size_t i = 0; i < len; ++i) putchar(result[i]);
    printf(" steps=%d\n", steps);
    free(result);
    return 0;
}
